const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const channel = text(input.channel || 'webchat').toLowerCase();
const external_conversation_id = text(input.external_conversation_id);
const mobile = text(input.mobile);
const direction = text(input.direction || 'inbound').toLowerCase();
const sender_type = text(input.sender_type || 'patient').toLowerCase();
const message_type = text(input.message_type || 'text').toLowerCase();
const message_text = text(input.message_text);
const language = text(input.language || 'fa').toLowerCase();
const session_expiry_hours = Number(input.session_expiry_hours ?? 24);
const context_message_limit = Number(input.context_message_limit ?? 20);
const confirm_message = toBoolean(input.confirm_message);

let messagePayload = input.message_payload ?? {};
if (typeof messagePayload === 'string') {
  const raw = messagePayload.trim();
  if (!raw) {
    messagePayload = {};
  } else {
    try {
      messagePayload = JSON.parse(raw);
    } catch {
      messagePayload = null;
    }
  }
}

const channels = [
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'webchat',
  'manual',
  'api',
];

const directions = ['inbound', 'outbound', 'internal'];
const senders = ['patient', 'assistant', 'human', 'system'];
const messageTypes = ['text', 'audio', 'image', 'file', 'event'];
const languages = ['fa', 'en', 'ar', 'unknown'];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!channels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال مکالمه معتبر نیست.',
  });
}

if (!external_conversation_id) {
  errors.push({
    field: 'external_conversation_id',
    message: 'شناسه خارجی مکالمه الزامی است.',
  });
}

if (external_conversation_id.length > 500) {
  errors.push({
    field: 'external_conversation_id',
    message: 'شناسه مکالمه بیش از حد طولانی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!directions.includes(direction)) {
  errors.push({
    field: 'direction',
    message: 'جهت پیام معتبر نیست.',
  });
}

if (!senders.includes(sender_type)) {
  errors.push({
    field: 'sender_type',
    message: 'نوع فرستنده معتبر نیست.',
  });
}

if (!messageTypes.includes(message_type)) {
  errors.push({
    field: 'message_type',
    message: 'نوع پیام معتبر نیست.',
  });
}

if (!message_text && (!messagePayload || Object.keys(messagePayload).length === 0)) {
  errors.push({
    field: 'message_text',
    message: 'متن یا داده ساختاریافته پیام الزامی است.',
  });
}

if (message_text.length > 12000) {
  errors.push({
    field: 'message_text',
    message: 'متن پیام نباید بیشتر از 12000 کاراکتر باشد.',
  });
}

if (messagePayload === null || Array.isArray(messagePayload) || typeof messagePayload !== 'object') {
  errors.push({
    field: 'message_payload',
    message: 'message_payload باید یک شیء JSON معتبر باشد.',
  });
}

if (!languages.includes(language)) {
  errors.push({
    field: 'language',
    message: 'زبان مکالمه معتبر نیست.',
  });
}

if (
  !Number.isInteger(session_expiry_hours) ||
  session_expiry_hours < 1 ||
  session_expiry_hours > 720
) {
  errors.push({
    field: 'session_expiry_hours',
    message: 'زمان اعتبار جلسه باید بین 1 و 720 ساعت باشد.',
  });
}

if (
  !Number.isInteger(context_message_limit) ||
  context_message_limit < 1 ||
  context_message_limit > 100
) {
  errors.push({
    field: 'context_message_limit',
    message: 'تعداد پیام‌های زمینه باید بین 1 و 100 باشد.',
  });
}

if (confirm_message !== true) {
  errors.push({
    field: 'confirm_message',
    message: 'ثبت پیام باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    channel,
    external_conversation_id,
    mobile,
    direction,
    sender_type,
    message_type,
    message_text,
    message_payload_json: JSON.stringify(messagePayload || {}),
    language,
    session_expiry_hours,
    context_message_limit,
    confirm_message,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات پیام یا جلسه مکالمه ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];
